mapper.select:

SELECT payment_metrics.paid_order_count,
       payment_metrics.paid_buyer_count,
       payment_metrics.gross_paid_amount,
       refund_metrics.successful_refund_amount,
       sold_metrics.sold_quantity,
       product_metrics.on_sale_product_count,
       review_metrics.displayed_review_count,
       review_metrics.average_rating
FROM (
    SELECT COUNT(*) AS paid_order_count,
           COUNT(DISTINCT p.user_id) AS paid_buyer_count,
           COALESCE(SUM(p.amount), 0.00) AS gross_paid_amount
    FROM payment_order p
    JOIN `order` o ON o.id = p.order_id
    WHERE o.shop_id = #{shopId}
      AND p.status IN (1, 4)
      AND p.pay_time >= #{startAt}
      AND p.pay_time < #{endAt}
) payment_metrics
CROSS JOIN (
    SELECT COALESCE(SUM(rf.amount), 0.00) AS successful_refund_amount
    FROM refund_order rf
    JOIN `order` o ON o.id = rf.order_id
    WHERE o.shop_id = #{shopId}
      AND rf.status = 1
      AND rf.refund_time >= #{startAt}
      AND rf.refund_time < #{endAt}
) refund_metrics
CROSS JOIN (
    SELECT COALESCE(SUM(oi.quantity), 0) AS sold_quantity
    FROM payment_order p
    JOIN `order` o ON o.id = p.order_id
    JOIN order_item oi ON oi.order_id = o.id
    WHERE o.shop_id = #{shopId}
      AND p.status IN (1, 4)
      AND p.pay_time >= #{startAt}
      AND p.pay_time < #{endAt}
) sold_metrics
CROSS JOIN (
    SELECT COUNT(*) AS on_sale_product_count
    FROM spu s
    WHERE s.shop_id = #{shopId}
      AND s.status = 'ON_SALE'
) product_metrics
CROSS JOIN (
    SELECT COUNT(*) AS displayed_review_count,
           AVG(rv.rating) AS average_rating
    FROM review rv
    WHERE rv.shop_id = #{shopId}
      AND rv.status = 'DISPLAYED'
) review_metrics
